def find_a(n, b):
    if n % 2 == 0:
        return "NO"

    mod = b[0] % b[1]
    for i in range(1, n):
        mod = (mod * mod) % mod
        if mod % b[i] != b[i + 1]:
            return "NO"
    return "YES"

def restore_a(n, b):
    if find_a(n, b) == "NO":
        return "NO"
    a = [b[0] % b[1]]
    for i in range(1, n):
        a.append((a[-1] * a[-1]) % abs(b[i]) % abs(a[-1]))
    return "YES" + "\n" + " ".join(map(str, a))

