import sys

def is_pure(sequence):
    """
    Checks if a binary string is pure.
    A string is considered pure if it does not contain the substrings "0101" or "1010" as subsequences.

    :param sequence: A binary string.
    :return: True if the sequence is pure, False otherwise.
    """
    for i in range(len(sequence)):
        if sequence[i] == '0':
            for j in range(i + 1, min(len(sequence), i + 4)):
                if sequence[j] == '1' and sequence[j+1] == '0':
                    return False
                if sequence[j] == '0' and sequence[j+1] == '1':
                    return False
    return True

def min_deletions_to_pure(sequence):
    """
    Finds the minimum number of deletions needed to make the binary string pure.

    :param sequence: A binary string.
    :return: The minimum number of deletions needed.
    """
    deletions = 0
    i = 0
    while True:
        if i == len(sequence) or sequence[i] == '0':
            break
        deletions += 1
        j = i
        while j < len(sequence) - 1 and sequence[j] == '1':
            j += 1
        if j < len(sequence) - 1:
            sequence = sequence[:j] + sequence[j+1:]
        if not is_pure(sequence):
            break
        i = j
    if len(sequence) == deletes:
        return deletions
    return deletes if is_pure(sequence) else deletions + 1

