def min_deletions(S):
    """
    Calculate the minimum number of deletions required to make the binary string S pure.
    A binary string is considered pure if it does not contain the subsequence "0101" or "1010".
    """
    pure_states = [[0 for _ in range(len(S))] for _ in range(len(S))]

    for i in range(len(S)-1, -1, -1):
        for j in range(i, len(S)):
            if S[i] == '0':
                if j+1 < len(S) and S[j+1] == '0':
                    pure_states[i][j] = pure_states[i+1][j-1]
                elif j+2 < len(S) and S[j+2] == '0':
                    pure_states[i][j] = pure_states[i+1][j-1] + 2
                else:
                    pure_states[i][j] = pure_states[i+1][j-1] + 1
            else:
                if j+1 < len(S) and S[j+1] == '1':
                    pure_states[i][j] = pure_states[i+1][j-1]
                elif j+2 < len(S) and S[j+2] == '1':
                    pure_states[i][j] = pure_states[i+1][j-1] + 2
                else:
                    pure_states[i][j] = pure_states[i+1][j-1] + 1
            if pure_states[i][j] == 0:
                if i == 0 or j == len(S)-1 or S[i] == '0' and j == len(S)-1 or (S[i] == '1' and pure_states[i+1][j-1] == 1):
                    return 0
    return pure_states[0][len(S)-1]

