def find_permutation(n, points, s):
    """
    Finds a permutation of points such that the polygonal line drawn satisfies the conditions.
    If no such permutation exists, returns -1.
    """

    def vector_angle(v1, v2):
        return math.atan2(v2[1], v2[0]) - math.atan2(v1[1], v1[0])

    # Base case
    if n == 2:
        return [1, 2]

    def ans(p, i, current_turn):
        if i >= n:
            return current_turn == -1
        if i < n - 1:
            v1 = (points[p[i+1]-1][0] - points[p[i]-1][0], 
                  points[p[i+1]-1][1] - points[p[i]-1][1])
            v2 = (points[p[i+2]-1][0] - points[p[i+1]-1][0], 
                  points[p[i+2]-1][1] - points[p[i+1]-1][1])
            if current_turn == vector_angle(v1, v2) == 1:
                return ans(p, i+1, -1)

        if i == n - 1:
            return ans(p, i+1, -1)

    # Recursive function to check all permutations
    result = -1
    for perm in itertools.permutations(range(1, n+1)):
        if ans(perm, 0, 0):
            result = perm
            break

    return result[1::] if result != -1 else "Permutation does not exist"

