from typing import List
from collections import Counter

def can_partition(permutation: List[int], k: int) -> bool:
    left, right = 1, len(permutation) - k + 1
    count = Counter(permutation)
    while left <= right:
        mid = (left + right) // 2
        if isValidPartition(permutation, k, count, mid):
            return True
        elif mid < len(permutation) - k + 1:
            left = mid + 1
        else:
            right = mid - 1
    return False

def isValidPartition(permutation: List[int], k: int, count: Counter, kPartition: int) -> bool:
    while kPartition > 1:
        if count.get(kPartition) == 0:
            return False
        elif count[kPartition] == 1:
            del count[kPartition]
            kPartition -= 1
        elif count[kPartition] == 2:
            del count[kPartition]
            del count[kPartition - 1]
            kPartition -= 2
        else:
            count[kPartition] -= 2
    return True

def find_k_beautiful_permutations(n: int, permutation: List[int], k: int) -> int:
    if can_partition(permutation, k):
        return 1
    return 0

