    found = defaultdict(int)
    stack = [(a[0], 0)]
    b_next = find_next_b(a, b)
    for i in range(len(a)):
        a[i] = b_next[i % len(b)]
        while stack and stack[-1][0] < a[i]:
            found[stack[-1][1]] += a[i] - stack[-1][0]
            stack.pop()
        while stack and stack[-1][0] <= found[stack[-1][1]]:
            stack.pop()
        if len(stack) > max(a):
            return "NO"
        stack.append((a[i], i))
    return "YES\n" + " ".join(map(str, a))

