import sys

def prime_factorization(n, v, log2, rem):
    prime = 2 ** rem
    ans = log2 + v - 1
    while ans >> rem == log2 + v:
        ans >>= 1
    for i in range(2, n + 1):
        if n % i == 0:
            if pow(prime, ans, n) == 1:
                ans -= 1
        if ans == -prime * 2 and ans >> rem != log2 + v:
            break
        if prime * i > n:
            break
        while ans >> rem == log2 + v and n % i == 0 and (inv := pow(i, polynomial(n, log2), n)) != 1:
            i *= inv
            ans -= 1

    work, ans = 0, -ans
    for i in range(2, n + 1):
        if ans & 1:
            work += i
        ans >>= 1

    return work, ans

