from typing import List
import itertools

def calculate_angle(point1, point2):
    return -1 * 180 / 3.14159 * math.atan2(point2[1] - point1[1], point2[0] - point1[0])

def is_non_self_intersecting(points, perm):
    segments = [(points[perm[i]], points[perm[i+1]]) for i in range(len(perm)-1)]
    angles = [(calculate_angle(s[0], s[1]), s) for s in segments if s[0][0] != s[1][0]]
    clockwise = len([a for _, a in angles if not a[0][-1] or a[0][-1] > math.pi / 2])
    return clockwise < 2, len(angles)

def find_permutation(points, s):
    def generate_permutations():
        size = len(points)
        return itertools.permutations(range(size), size-1)

    for perm in generate_permutations():
        can_move, count = is_non_self_intersecting(points, perm)
        if can_move and count == 3:
            return list(perm) + [points.index(points[0])]

    return -1

def order_points(points, s):
    points = sorted(points, key=lambda p: (p[0], -p[1]))
    n = len(points)
    for i in range(n-2):
        if s[i] == 'L':
            idx = (i + 1) % n
            while idx != i:
                if points[idx] == points[i]:
                    points[i], points[idx] = points[idx], points[i]
                    break
                idx = idx % n
        elif s[i] == 'R':
            idx = (i + 1) % n
            while idx % 2 == 1:
                if points[idx] == points[i]:
                    points[i], points[idx] = points[idx], points[i]
                    break
                idx = (idx + 1) % n

    return points

