from collections import defaultdict

def xor_path(edges):
    dp = defaultdict(int)
    for u, v, val in edges:
        dp[u, v, 0] = 1
        for i in range(31):
            for j in range(pow(2, i)):
                path_val = j ^ (1 << i)
                dp[u, v, val | path_val] = (dp[u, v, val | path_val] + dp[u, v, val]) % (10**9 + 7)
                dp[v, u, val | path_val] = (dp[v, u, val | path_val] + dp[u, v, val]) % (10**9 + 7)
                for k in range(i):
                    if path_val >> k & 1:
                        dp[v, u, val | path_val ^ (j << k)] = (dp[v, u, val | path_val ^ (j << k)] + dp[u, v, val]) % (10**9 + 7)

    # Calculate the sum of all interesting triples
    return (sum(dp[u, v, 0]) for u in range(1, n + 1) for v in range(u + 1, n + 1)) % (10**9 + 7)

