from collections import defaultdict, deque

def find_circle(edges):
    graph = defaultdict(list)

    # Build tree
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    # Union Find to find cycle
    def find(x):
        if parents[x] != x:
            parents[x] = find(parents[x])
        return parents[x]

    parent = {}

    for v in range(1, n+1):
        if v not in parent:
            parents[v] = v

    for v in range(1, n+1):
        for neigh in graph[v]:
            if find(v) != find(neigh):
                parents[find(neigh)] = find(v)

    # bfs from a single node and write if connected (cycle)
    queue = deque([1])
    got_cycle = False
    connected_components = 0
    while queue:
        cwnd = queue.popleft()
        got_cycle = got_cycle or parent[cwnd] == cwnd
        for neigh in graph[cwnd]:
            if neigh != cwnd and not got_cycle:
                parents[find(neigh)] = neigh
                queue.append(neigh)
        connected_components += 1
        queue.append(cwnd)
        if got_cycle:
            break

    return (-1 if n % 2 else connected_components // 2)

