def check_points(points, n, order):
    for i in range(n - 1):
        dim = 2
        pi, pi_1 = points[order[i] - 1]
        pi_2, pi_3 = points[order[(i + 1) % n] - 1]
        v1 = (pi_2 - pi), (pi_3 - pi)
        v2 = (pi_1 - pi_2), (pi_3 - pi_2)
        angle = (v1[0] * v2[1] - v1[1] * v2[0]) / (abs(v1) * abs(v2))
        if angle > 0:
            yield 'right'
        else:
            yield 'left'

def solve(n, points, s):
    possible = [1] * n
    for perm in permutations(range(1, n + 1)):
        if all(w in check_points(points, n, perm) for w in s):
            return perm
    return -1

