def find_ceiling_support_adjustment(x1, x2, xcs, xs, dcs):
    n = len(xs)-1
    for i in range(n):
        dx = xcs[i+1]-xcs[i]
        if x1 - (dcs[i]*dx/2) < xs[i] < x1 + (dcs[i]*dx/2) and x2 - (dcs[i]*dx/2) > xs[i] > x2 + (dcs[i]*dx/2):
            return 0
    return max(max(dcs[x1], dcs[x2]) - (dcs[x1]*dx/2), (dcs[x1]*dx/2-1))

def minimize_adjustment(n, xcs, xs, dcs, x_opt):
    if min(dcs) - xs[n] <= x_opt:
        return 0
    x1, x2 = xcs[0], xcs[n]
    return find_ceiling_support_adjustment(x1, x2, xcs, xs, dcs)

