import heapq

def find_min_bunch(tree_nodes, k):
    n = len(tree_nodes)
    distance_to_root = [0] * n
    for root in range(n):
        visited = set([root])
        queue = [(0, root)]
        while queue:
            dist, node = heapq.heappop(queue)
            distance_to_root[node] = dist
            for neighbor in tree_nodes[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    heapq.heappush(queue, (dist + 1, neighbor))
    max_dist = max(distance_to_root)
    leaves = [i for i in range(n) if distance_to_root[i] == max_dist and root_in_tree_edge(i, tree_nodes)]

    min_bunch = 1
    while leaves:
        new_bunch = []
        for leaf in leaves:
            heapq.heappush(new_bunch, leaf)
        while new_bunch:
            node = heapq.heappop(new_bunch)
            distance_to_root[node] = k
            for neighbor in tree_nodes[node]:
                if neighbor not in new_bunch and root_in_tree_edge(neighbor, tree_nodes):
                    heapq.heappush(new_bunch, neighbor)
        if not new_bunch:
            break
        else:
            leaves = new_bunch
            min_bunch += 1
    return min_bunch

def root_in_tree_edge(node, tree_nodes):
    return node in set([i for sublist in tree_nodes for i in sublist])

