def min_deletions_pure_binary_string(S):
    n = len(S)
    # Initialize dp array where dp[i][j] represents the minimum deletions to make S[0:i] pure ending at j
    dp = [[0] * 2 for _ in range(n)]
    for i in range(n):
        for j in range(2):
            if i == 0 and j == 0 or i == 0 and j == 1:
                dp[i][j] = S[i]
            elif i > 0 and j == 0:
                dp[i][j] = dp[i-1][0] + S[i] if S[i] != '0' else dp[i-1][1] + S[i]
            elif i > 0 and j == 1:
                dp[i][j] = dp[i-1][0] + S[i] if S[i] != '1' else dp[i-1][1] + S[i]
    return min(dp[-1])

