            if left_bearing_index is not None and left_bearing_index + 1 < len(x_points) and x_points[left_bearing_index + 1] - x_points[left_bearing_index] <= current_length:
                left_bearing_depth = min(durability[left_bearing_index], durability[left_bearing_index + 1])
                right_bearing_index = find_right_bearing_index(x_points, x_points[left_bearing_index:i+2], current_length)
                if right_bearing_index is not None and right_bearing_index <= n and x_points[right_bearing_index] - x_points[left_bearing_index + 1] <= current_length:
                    right_bearing_depth = min(durability[right_bearing_index], durability[right_bearing_index + 1])
                    optimal_durability = min(optimal_durability, left_bearing_depth + right_bearing_depth)

        if optimal_durability != math.inf:
            if current_length * total_support == optimal_durability:
                return total_length - optimal_durability
    return 0

def find_left_bearing_index(x_points, segment, max_length):
    start, end = 0, len(x_points)
    if len(x_points) < 2:
        return None
    if len(segment) + start < end:
        return None

    while start < end:
        mid = (start + end) // 2
        if segment[mid-1] - x_points[0] <= max_length:
            start = mid
        else:
            end = mid - 1
    return start

def find_right_bearing_index(x_points, segment, max_length):
    start, end = 0, len(x_points) - 1
    if len(x_points) < 2:
        return None
    if len(segment) + start < end:
        return None

    while start < end:
        mid = (start + end) // 2
        if segment[mid] - x_points[-1] <= max_length:
            end = mid
        else:
            start = mid + 1
    return start

def handle_input(fn):
    n, x_points, durability = fn()
    return n, find_optimal_column_position(n, x_points, durability)

def check_solution(result):
    pass

if __name__ == "__main__":
    n, x_points, durability = process_input()
    result = handle_input(get_length_fn)
    check_solution(result)
