def dfs(tree, low, leaves, leaves_count, level, dp, k):
    max_level = level + 1
    leaf_count = 0
    for child in tree:
        if child not in leaves:
            dp[child] = [0] + dp[child]  # Initialize dp array for children with current level
            if child not in dp:
                dp[child] = [level + 1]
            child_leaves = dfs(tree, low, child, leaves_count, level + 1, dp, k)  # Recursive DFS on child
            for child_level in child_leaves:
                if child_level <= k and child_level > max_level:
                    max_level = child_level  # Update max level if it exceeds previous max with necessary conditions
                dp[child][-1] = max(dp[child][-1], child_level+1)  # Update maximum distance to include child's level
            leaf_count += len(child_leaves)
    if max_level <= k:
        return leaf_count
    return max(leaves_count - 1, not max(dp) > k)  # Split with necessary distance condition

def findMaxLeafCount(n, k):
    if k >= n - 1:
        return n
    tree = [[] for _ in range(n)]
    for i in range(n - 1):
        u, v = map(int, input().split())
        tree[u - 1].append(v - 1)
        tree[v - 1].append(u - 1)
    dp = [1] * n  # Default to each leaf as 1 good free
    leaves = set(i + 1 for i, l in enumerate(tree) if len(l) == 1)  # Get set of unique leaf nodes
    return dfs(min(bytewise_count(tree)), 0, leaves, 1, 0, dp, k)  # Main DFS function
