def max_four_track_notes(n, notes):
    notes.sort()
    long_notes = [notes[-1]]

    for note in notes[-3::-1]:
        if note + 1 in notes and (note % 7 != (long_notes[-1] % 7)):
            long_notes.append(note)

    return sum(long_notes[:4])

